DNA_KEYS = [
    "romance",
    "fantasy_romantasy",
    "thriller_mystery_crime",
    "science_fiction",
    "horror",
    "personal_development_nonfiction",
    "young_adult",
]

PROFILE_KEYS = [
    "emotional",
    "mysterious",
    "easy_to_read",
    "tearjerker",
    "dark",
    "intellectually_challenging",
    "relaxing",
    "thought_provoking",
    "wholesome",
]


def normalize_title(title: str) -> str:
    import re
    import unicodedata

    normalized = unicodedata.normalize(
        "NFKD",
        title,
    )

    normalized = "".join(
        char
        for char in normalized
        if not unicodedata.combining(char)
    )

    normalized = normalized.lower()

    normalized = re.sub(
        r"[^\w\s]",
        " ",
        normalized,
    )

    normalized = re.sub(
        r"\s+",
        " ",
        normalized,
    )

    return normalized.strip()


def build_book(data: dict) -> Book:
    book_dna = dict(
        zip(
            DNA_KEYS,
            data["dna"],
        )
    )

    reading_profile = dict(
        zip(
            PROFILE_KEYS,
            data["profile"],
        )
    )

    reading_profile["short_book"] = (
        100
        if data["page_count"] < 200
        else 0
    )

    return Book(
        title=data["title"],
        authors=data["authors"],
        publisher=None,
        page_count=data["page_count"],
        published_year=None,
        language="en",
        categories=data["categories"],
        description=data["summary"],
        preview_link="https://books.google.com/",
        google_rating=data["rating"],
        ratings_count=10000,
        thumbnail=None,
        ai_summary=data["summary"],
        book_dna=book_dna,
        reading_profile=reading_profile,
        themes=data["themes"],
        atmosphere=data["atmosphere"],
        story_elements=data["elements"],
        source="Seed",
    )


def seed_books() -> None:
    db = SessionLocal()

    inserted = 0
    skipped = 0

    try:
        print("\n🌱 Starting BookMind mixed genre seed...\n")

        existing_books = db.query(Book).all()

        existing_titles = {
            normalize_title(book.title)
            for book in existing_books
            if book.title
        }

        for data in BOOKS:
            normalized_title = normalize_title(
                data["title"]
            )

            if normalized_title in existing_titles:
                print(
                    f"⏭️ Already exists: "
                    f"{data['title']}"
                )
                skipped += 1
                continue

            db.add(build_book(data))

            existing_titles.add(
                normalized_title
            )

            inserted += 1

            print(
                f"✅ Added: "
                f"{data['title']} "
                f"({data['page_count']} pages)"
            )

        db.commit()

        print("\n" + "=" * 60)
        print("🌱 MIXED GENRE SEED COMPLETE")
        print("=" * 60)
        print(f"📚 Inserted: {inserted}")
        print(f"⏭️ Skipped: {skipped}")
        print(f"📦 Books in this seed: {len(BOOKS)}")
        print("=" * 60)

    except Exception as exc:
        db.rollback()
        print(
            f"\n❌ Seed failed: {exc}"
        )
        raise

    finally:
        db.close()


if __name__ == "__main__":
    seed_books()